});
s_waitcnt_lgkmcnt(0_I);
__builtin_amdgcn_s_barrier();
if (wk == (lane % T::W_M) % T::WAVE_K) {
static_for<T::E_M * T::E_N>([&](auto i) {
c[decltype(i)::value] = load<elem_c>(shared,
offset + decltype(i)::value * 64 * elem_c);
});
