int run_output3_row_owner(int group, int variant,
const void* a, const void* b, void* out,
const void* sfa, const void* sfb,
int m, int n, int k, void* stream) {
if (group < 0 || group >= 15 || variant < 0 || variant > 1) return -1;
if (m <= 0 || n <= 0 || k <= 0 || n % 128 || k % 128 || k > 16384) return -3;
if (!a || !b || !out || !sfa || !sfb) return -4;
if (int64_t{m} * k > INT_MAX || int64_t{n} * k > INT_MAX ||
int64_t{2} * m * n > INT_MAX || int64_t{m} * (k / 128) > INT_MAX) return -5;
if (reinterpret_cast<uintptr_t>(a) % 16 || reinterpret_cast<uintptr_t>(b) % 16 ||
reinterpret_cast<uintptr_t>(out) % 16 || reinterpret_cast<uintptr_t>(sfa) % 16) return -6;
const uintptr_t output = reinterpret_cast<uintptr_t>(out);
const uint64_t output_bytes = uint64_t{2} * m * n;
const void* inputs[] = {a, b, sfa, sfb};
const uint64_t input_bytes[] = {uint64_t{1} * m * k, uint64_t{1} * n * k,
uint64_t{1} * m * (k / 128), uint64_t{1} * (n / 128) * (k / 128)};
if (output_bytes > UINTPTR_MAX - output) return -8;
for (int i = 0; i < 4; ++i) {
const uintptr_t begin = reinterpret_cast<uintptr_t>(inputs[i]);
