const int lane = thread_id_x() % 64;
const int wave = __builtin_amdgcn_readfirstlane(thread_id_x() / 64);
const int wm = wave % T::T_M;
const int wn = (wave / T::T_M) % T::T_N;
const int wk = wave / (T::T_M * T::T_N);
