const int group=(col+nr)/128;
static_for<SCALE_WORDS>([&](auto wi) {
constexpr int word=decltype(wi)::value;
const int begin=(first_scale_word+word)*4;
unsigned packed=0;
if constexpr((768/128)%4==0) {
if(begin<768/128)
packed=load<1>(packed_b_scales,group*(768/128/4)+first_scale_word+word)[0];
} else {
static_for<4>([&](auto bi) {
constexpr int byte=decltype(bi)::value;
if(begin+byte<768/128)
packed|=static_cast<unsigned>(load<1>(gsb,group*(768/128)+begin+byte)[0])<<(byte*8);
});
