const int total_tiles = (T::FIXED_K ? T::FIXED_K : 7168) / T::W_K;
const int tiles_per_wave = total_tiles / T::WAVE_K;
const int extra_tiles = total_tiles % T::WAVE_K;
const int loops = tiles_per_wave + (wk < extra_tiles);
const int tile_begin = wk * tiles_per_wave + (wk < extra_tiles ? wk : extra_tiles);
const int scale_groups = 7168 / 128;
auto ga = make_gmem(reinterpret_cast<const fp8_t*>(args.ptr_a) + row * 7168,
static_cast<unsigned>((1 - row) * 7168));
auto gb = make_gmem(reinterpret_cast<const fp8_t*>(args.ptr_b) + col * 7168,
T::N_TAIL ? static_cast<unsigned>((768 - col) * 7168) : 0xffffffffu);
auto gsa = make_gmem(reinterpret_cast<const unsigned char*>(args.ptr_sfa),
static_cast<unsigned>(1 * scale_groups));
auto gsb = make_gmem(reinterpret_cast<const unsigned char*>(args.ptr_sfb),
T::N_TAIL ? static_cast<unsigned>(768 / 128 * scale_groups) : 0xffffffffu);
auto gc = make_gmem(reinterpret_cast<bf16_t*>(args.ptr_c) + row * 768 + col,
static_cast<unsigned>(((1 - row) * 768 - col) * 2));
