if constexpr((7168/128)%4==0) {
if(begin<7168/128)
packed=load<1>(packed_b_scales,group*(7168/128/4)+first_scale_word+word)[0];
} else {
static_for<4>([&](auto bi) {
constexpr int byte=decltype(bi)::value;
if(begin+byte<7168/128)
packed|=static_cast<unsigned>(load<1>(gsb,group*(7168/128)+begin+byte)[0])<<(byte*8);
});
}
b_scale_words[ni0][word]=packed;
});
});
