const int r = (m * T::T_M + wm) * T::W_M + lane % T::W_M;
const int offset = r * 7168 + (lane / T::W_M) * 16;
set_slice(q.a[m], load<16>(ga, offset, kt * T::W_K), 0_I, 16_I);
set_slice(q.a[m], load<16>(ga, offset + T::W_K / 2, kt * T::W_K), 16_I, 32_I);
